use rtrb::{RingBuffer, PopError};
fn main() {
    let (mut p, mut c) = RingBuffer::<i32>::new(4);
    std::thread::spawn(move || {
        p.push(1).unwrap();
        p.push(2).unwrap();
    }).join().unwrap();
    assert_eq!(c.pop(), Ok(1));
    assert_eq!(c.pop(), Ok(2));
    assert_eq!(c.pop(), Err(PopError::Empty));
    println!("ok");
}

