use rtrb::{RingBuffer, PopError};
fn main() {
    let (mut prod, mut cons) = RingBuffer::<f32>::new(16);
    prod.push(0.5).unwrap();
    prod.push(-0.5).unwrap();
    let mut buf = [0.0f32; 4];
    for s in buf.iter_mut() {
        *s = cons.pop().unwrap_or(0.0);
    }
    assert_eq!(buf, [0.5, -0.5, 0.0, 0.0]);
    println!("ok");
}

